import {
  Column,
  CreateDateColumn,
  DeleteDateColumn,
  Entity,
  JoinTable,
  ManyToMany,
  PrimaryColumn,
  Unique,
  UpdateDateColumn,
} from 'typeorm';
import { EcoregionOrmEntity } from '../../ecoregions/infrastructure/ecoregion.orm-entity.js';
import {
  AnimalClass,
  ConservationStatus,
  PopulationTrend,
} from '../domain/enums.js';

/** Persistence model of an Animal. Mapped to/from the domain in the repository. */
@Entity('animals')
@Unique('UQ_animals_scientific_name', ['scientificName'])
export class AnimalOrmEntity {
  // The id is generated by the domain (Animal.create).
  @PrimaryColumn('uuid', { primaryKeyConstraintName: 'PK_animals_id' })
  id: string;

  @Column({ name: 'common_name_es', length: 150 })
  commonNameEs: string;

  @Column({
    name: 'common_name_en',
    type: 'varchar',
    length: 150,
    nullable: true,
  })
  commonNameEn: string | null;

  @Column({ name: 'scientific_name', length: 150 })
  scientificName: string;

  @Column({
    name: 'animal_class',
    type: 'enum',
    enum: AnimalClass,
    enumName: 'animal_class_enum',
  })
  animalClass: AnimalClass;

  @Column({ name: 'description_es', type: 'text', nullable: true })
  descriptionEs: string | null;

  @Column({ name: 'description_en', type: 'text', nullable: true })
  descriptionEn: string | null;

  @Column({
    name: 'iucn_status',
    type: 'enum',
    enum: ConservationStatus,
    enumName: 'conservation_status_enum',
  })
  iucnStatus: ConservationStatus;

  @Column({
    name: 'bolivia_red_book_status',
    type: 'enum',
    enum: ConservationStatus,
    enumName: 'conservation_status_enum',
    nullable: true,
  })
  boliviaRedBookStatus: ConservationStatus | null;

  @Column({ name: 'threats_es', type: 'text', nullable: true })
  threatsEs: string | null;

  @Column({ name: 'threats_en', type: 'text', nullable: true })
  threatsEn: string | null;

  @Column({
    name: 'population_trend',
    type: 'enum',
    enum: PopulationTrend,
    enumName: 'population_trend_enum',
    nullable: true,
  })
  populationTrend: PopulationTrend | null;

  @Column({ name: 'estimated_population', type: 'integer', nullable: true })
  estimatedPopulation: number | null;

  @Column({ name: 'habitat_es', length: 255 })
  habitatEs: string;

  @Column({ name: 'habitat_en', type: 'varchar', length: 255, nullable: true })
  habitatEn: string | null;

  @Column({ length: 255 })
  distribution: string;

  @Column({ name: 'photo_url', type: 'varchar', length: 500, nullable: true })
  photoUrl: string | null;

  @Column({
    name: 'photo_thumbnail_url',
    type: 'varchar',
    length: 500,
    nullable: true,
  })
  photoThumbnailUrl: string | null;

  @Column({
    name: 'photo_public_id',
    type: 'varchar',
    length: 255,
    nullable: true,
  })
  photoPublicId: string | null;

  @Column({
    name: 'photo_credit',
    type: 'varchar',
    length: 255,
    nullable: true,
  })
  photoCredit: string | null;

  @Column({ name: 'source_reference', length: 500 })
  sourceReference: string;

  @ManyToMany(() => EcoregionOrmEntity)
  @JoinTable({
    name: 'animal_ecoregions',
    joinColumn: {
      name: 'animal_id',
      referencedColumnName: 'id',
      foreignKeyConstraintName: 'FK_animal_ecoregions_animal',
    },
    inverseJoinColumn: {
      name: 'ecoregion_id',
      referencedColumnName: 'id',
      foreignKeyConstraintName: 'FK_animal_ecoregions_ecoregion',
    },
  })
  ecoregions: EcoregionOrmEntity[];

  @CreateDateColumn({ name: 'created_at', type: 'timestamptz' })
  createdAt: Date;

  @UpdateDateColumn({ name: 'updated_at', type: 'timestamptz' })
  updatedAt: Date;

  @DeleteDateColumn({ name: 'deleted_at', type: 'timestamptz' })
  deletedAt: Date | null;
}
